def dar_rol_administrador(apps, schema_editor):
    """Las cuentas que ya existían administraban el panel: no se degradan.

    Sin esta pasada, desplegar el modelo sin tocar `permisos.rol_de` dejaría
    fuera de la aplicación a quien la estaba usando.
    """
    Usuario = apps.get_model('auth', 'User')
    UsuarioPanel = apps.get_model('licencias', 'UsuarioPanel')
    for usuario in Usuario.objects.filter(is_superuser=True):
        UsuarioPanel.objects.get_or_create(
            usuario=usuario, defaults={'rol': 'administrador'})


